/*
path :           app/admin/users/actions.ts
tag :            ["admin", "users", "action", "role", "server-action", "bootstrap"]
projectId:       new-genesis
type :           action
generic:         false

role:            Server Action de mise à jour du rôle d'un utilisateur.
                 Règles d'autorisation :
                 1. Authentification requise (getSession).
                 2. Cas bootstrap : si AUCUN admin n'existe en base,
                    un utilisateur peut se promouvoir LUI-MÊME admin
                    (self-promotion) une seule fois. Cela résout le
                    chicken-and-egg sans faille exploitable : dès le
                    premier admin créé, la règle tombe.
                 3. Cas normal : l'appelant doit être admin pour
                    modifier le rôle de n'importe qui.
                 4. Un admin ne peut pas se rétrograder lui-même s'il
                    est le dernier admin (garde-fou anti-lockout).
                 Validation role ∈ {"user","admin"}. Revalide
                 /admin/users.

flow:            updateUserRoleAction(userId, role) → getSession() →
                 si null : erreur → validation role → count admins
                 en base → si 0 admins ET userId === session.user.id :
                 autoriser (bootstrap) → sinon : fetch caller.role →
                 si caller.role !== "admin" : erreur → si caller.id
                 === userId et role === "user" et adminCount <= 1 :
                 erreur "dernier admin" → prisma.user.update →
                 revalidatePath → {ok, data}.

ecosystem:       Admin = [
                   "@/app/admin/users/actions.ts",
                   "@/app/admin/users/page.tsx",
                   "@/app/admin/users/RoleSelect.tsx",
                 ]

relatedFiles:    ["@/lib/prisma.ts",
                  "@/lib/auth/session.ts",
                  "@/app/blog/lib/actions/result.ts"]

imports:         ["next/cache",
                  "@/lib/prisma",
                  "@/lib/auth/session",
                  "@/app/blog/lib/actions/result"]

exports:         ["updateUserRoleAction"]

useBy:           ["@/app/admin/users/RoleSelect.tsx"]

userStories:     ["*en tant qu'administrateur je veux changer le rôle d'un utilisateur",
                  "us1100012"]
status:          wip
pathChecked:     ✔true
metaDataChecked: ✔true
scriptChecked:   ✔true
*/

"use server";

import { revalidatePath } from "next/cache";

import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth/session";
import {
  handleActionError,
  type ActionResult,
} from "@/app/blog/lib/actions/result";

const VALID_ROLES = new Set(["user", "admin"]);

export async function updateUserRoleAction(
  userId: string,
  role: string,
): Promise<ActionResult<null>> {
  try {
    /* 1. Authentification */
    const session = await getSession();
    if (!session?.user) {
      return { ok: false, error: "Authentification requise." };
    }

    /* 2. Validation du rôle cible */
    if (!VALID_ROLES.has(role)) {
      return { ok: false, error: `Rôle invalide : ${role}.` };
    }

    const callerId = session.user.id;
    const isSelf = callerId === userId;

    /* 3. Compter les admins existants (pour bootstrap + anti-lockout) */
    const adminCount = await prisma.user.count({
      where: { role: "admin", deletedAt: null },
    });

    /* 4. Cas bootstrap : aucun admin + self-promotion admin */
    const isBootstrap = adminCount === 0 && isSelf && role === "admin";

    if (!isBootstrap) {
      /* 5. Cas normal : l'appelant doit être admin */
      const caller = await prisma.user.findUnique({
        where: { id: callerId },
        select: { role: true },
      });
      if (caller?.role !== "admin") {
        return { ok: false, error: "Rôle administrateur requis." };
      }

      /* 6. Anti-lockout : dernier admin ne peut pas se rétrograder */
      if (isSelf && role === "user" && adminCount <= 1) {
        return {
          ok: false,
          error:
            "Impossible de retirer le rôle au dernier administrateur. Nommez d'abord un autre admin.",
        };
      }
    }

    /* 7. Mise à jour */
    await prisma.user.update({
      where: { id: userId },
      data: { role },
    });

    revalidatePath("/admin/users");
    return { ok: true, data: null };
  } catch (error) {
    return handleActionError(error);
  }
}

/*
path :           app/admin/users/page.tsx
tag :            ["admin", "users", "page", "read", "update", "role"]
projectId:       new-genesis
type :           page
generic:         false

role:            Administration utilisateurs. Utilise LoginCTA pour
                 l'anonyme.

flow:            AdminUsersPage (sync) → Suspense → UsersSection
                 async → getSession → si null : <LoginCTA /> →
                 fetch caller.role → si !== "admin" : accès refusé →
                 prisma.user.findMany → rend tableau + RoleSelect.

ecosystem:       Admin = [
                   "@/app/admin/users/actions.ts",
                   "@/app/admin/users/page.tsx",
                   "@/app/admin/users/RoleSelect.tsx",
                 ]

relatedFiles:    ["@/lib/prisma.ts",
                  "@/lib/auth/session.ts",
                  "@/app/blog/lib/actions/result.ts",
                  "@/utils/date.ts",
                  "@/components/auth/LoginCTA.tsx"]

imports:         ["react", "lucide-react",
                  "@/lib/prisma",
                  "@/lib/auth/session",
                  "@/components/auth/LoginCTA",
                  "@/components/ui/skeleton",
                  "@/app/admin/users/RoleSelect",
                  "@/utils/date"]

exports:         ["default AdminUsersPage"]

useBy:           []

userStories:     ["*en tant qu'administrateur je veux gérer les utilisateurs et leurs rôles"]

status:          done
pathChecked:     ✔true
metaDataChecked: ✔true
scriptChecked:   ✔true
*/

import { Suspense } from "react";
import { Shield, Users } from "lucide-react";

import { prisma } from "@/lib/prisma";
import { getSession } from "@/lib/auth/session";
import { LoginCTA } from "@/components/auth/LoginCTA";
import { Skeleton } from "@/components/ui/skeleton";
import { RoleSelect } from "@/app/admin/users/RoleSelect";
import { formatDateShort } from "@/utils/date";

export default function AdminUsersPage() {
  return (
    <div className="mx-auto w-full max-w-4xl space-y-6 px-4 py-10 sm:px-6">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-[11px] font-semibold uppercase tracking-wider text-chart-1">
            Administration
          </p>
          <h1 className="flex items-center gap-2 text-2xl font-bold tracking-tight text-foreground">
            <Users className="size-5 text-chart-1" aria-hidden />
            Utilisateurs
          </h1>
        </div>
        <p className="text-xs text-muted-foreground">
          Modifiez le rôle d&apos;un utilisateur. Le dernier administrateur
          ne peut pas être rétrogradé.
        </p>
      </header>

      <Suspense fallback={<UsersSkeleton />}>
        <UsersSection />
      </Suspense>
    </div>
  );
}

async function UsersSection() {
  const session = await getSession();
  if (!session?.user) {
    return (
      <LoginCTA message="Connectez-vous pour accéder à la gestion des utilisateurs." />
    );
  }

  const caller = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { role: true },
  });
  if (caller?.role !== "admin") {
    return (
      <div className="rounded-2xl border border-destructive/40 bg-destructive/5 p-8 text-center">
        <Shield
          className="mx-auto mb-2 size-8 text-destructive"
          aria-hidden
        />
        <p className="text-sm text-destructive">
          Accès réservé aux administrateurs.
        </p>
      </div>
    );
  }

  const users = await prisma.user.findMany({
    where: { deletedAt: null },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      createdAt: true,
    },
    orderBy: { createdAt: "asc" },
  });

  const adminCount = users.filter((u) => u.role === "admin").length;

  return (
    <div className="space-y-3">
      <div className="overflow-hidden rounded-2xl border border-border/60 bg-card">
        <table className="w-full">
          <thead className="border-b border-border/60 bg-muted/30">
            <tr>
              <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Nom
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Email
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Rôle
              </th>
              <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Inscrit le
              </th>
            </tr>
          </thead>
          <tbody>
            {users.map((user) => {
              const isLastAdmin =
                user.role === "admin" && adminCount <= 1;
              return (
                <tr
                  key={user.id}
                  className="border-b border-border/40 last:border-b-0"
                >
                  <td className="px-4 py-3 text-sm text-foreground">
                    {user.name}
                  </td>
                  <td className="px-4 py-3 text-sm text-muted-foreground">
                    {user.email}
                  </td>
                  <td className="px-4 py-3">
                    <RoleSelect
                      userId={user.id}
                      currentRole={user.role ?? "user"}
                      disabled={isLastAdmin}
                    />
                  </td>
                  <td className="px-4 py-3 text-sm text-muted-foreground">
                    {formatDateShort(user.createdAt)}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {users.length === 0 && (
          <p className="p-8 text-center text-sm text-muted-foreground">
            Aucun utilisateur en base.
          </p>
        )}
      </div>

      <p className="text-xs text-muted-foreground">
        {adminCount} administrateur{adminCount > 1 ? "s" : ""} actif
        {adminCount > 1 ? "s" : ""} · le dernier ne peut pas être
        rétrogradé.
      </p>
    </div>
  );
}

function UsersSkeleton() {
  return (
    <div className="space-y-2">
      <Skeleton className="h-12 w-full rounded-xl" />
      <Skeleton className="h-12 w-full rounded-xl" />
      <Skeleton className="h-12 w-full rounded-xl" />
    </div>
  );
}

/*
path :           app/admin/users/RoleSelect.tsx
tag :            ["admin", "users", "role", "select", "client", "update"]
projectId:       new-genesis
type:            component
generic:         false

role:            Sélecteur de rôle pour un utilisateur. Affiche un
                 <select> avec "Utilisateur" / "Administrateur". Au
                 changement, appelle updateUserRoleAction(userId, role)
                 via useActionResult (toast + rollback optimiste). La
                 prop `disabled` permet au parent de bloquer l'édition
                 (ex. dernier admin) — le serveur refuse aussi
                 (anti-lockout).

flow:            Props { userId, currentRole, disabled? } →
                 useState(role) → onChange → optimistic setRole(nextRole)
                 → useActionResult.run(() => updateUserRoleAction, {
                 successMessage, rollback: () => setRole(previous) }).

ecosystem:       Admin = [
                   "@/app/admin/users/actions.ts",
                   "@/app/admin/users/page.tsx",
                   "@/app/admin/users/RoleSelect.tsx",
                 ]

relatedFiles:    ["@/app/admin/users/actions.ts",
                  "@/hooks/useActionResult.ts"]

imports:         ["react",
                  "@/app/admin/users/actions",
                  "@/components/ui/native-select",
                  "@/hooks/useActionResult"]

exports:         ["RoleSelect", "RoleSelectProps"]

useBy:           ["@/app/admin/users/page.tsx"]

userStories:     ["*en tant qu'administrateur je veux changer le rôle d'un utilisateur"]
status:          done
pathChecked:     ✔true
metaDataChecked: ✔true
scriptChecked:   ✔true
*/

"use client";
// "use client" justifié : useState + useActionResult.

import { useState } from "react";

import { updateUserRoleAction } from "@/app/admin/users/actions";
import {
  NativeSelect,
  NativeSelectOption,
} from "@/components/ui/native-select";
import { useActionResult } from "@/hooks/useActionResult";

export interface RoleSelectProps {
  readonly userId: string;
  readonly currentRole: string;
  readonly disabled?: boolean;
}

export function RoleSelect({
  userId,
  currentRole,
  disabled = false,
}: RoleSelectProps) {
  const [role, setRole] = useState(currentRole);
  const { run, isPending } = useActionResult();

  function handleChange(nextRole: string) {
    const previous = role;
    setRole(nextRole);

    run(() => updateUserRoleAction(userId, nextRole), {
      successMessage: `Rôle mis à jour : ${nextRole}.`,
      rollback: () => setRole(previous),
    });
  }

  return (
    <NativeSelect
      value={role}
      onChange={(e) => handleChange(e.target.value)}
      disabled={disabled || isPending}
      className="w-32"
      aria-label="Rôle de l'utilisateur"
    >
      <NativeSelectOption value="user">Utilisateur</NativeSelectOption>
      <NativeSelectOption value="admin">Administrateur</NativeSelectOption>
    </NativeSelect>
  );
}

/*
path :           app/auth/login/LoginForm.tsx
projectId:       new-genesis
type:            component
generic:         false

role:            Formulaire de connexion email + mot de passe. Utilise react-hook-form,
                 zodResolver(loginSchema), PasswordInput et Field shadcn.

flow:            Client Component → useForm → onSubmit → signIn.email() → si erreur :
                 setFormError avec message adapté (401/400/429/autre) → si succès :
                 toast + router.replace(callbackUrl) + router.refresh().

ecosystem:       Auth = [
                   "@/app/api/auth/[...all]/route.ts",
                   "@/app/auth/layout.tsx",
                   "@/app/auth/login/LoginForm.tsx",
                   "@/app/auth/login/page.tsx",
                   "@/app/auth/register/RegisterForm.tsx",
                   "@/app/auth/register/page.tsx",
                   "@/app/auth/welcome/page.tsx",
                   "@/components/auth/PasswordInput.tsx",
                   "@/components/auth/PasswordStrength.tsx",
                   "@/lib/auth/auth-client.ts",
                   "@/lib/auth/auth.ts",
                   "@/lib/auth/session.ts",
                   "@/lib/validations/auth.ts",
                 ]

relatedFiles:    ["@/app/auth/login/page.tsx",
                  "@/components/auth/PasswordInput.tsx",
                  "@/lib/auth/auth-client.ts",
                  "@/lib/validations/auth.ts",
                  "@/components/ui/alert.tsx",
                  "@/components/ui/button.tsx",
                  "@/components/ui/field.tsx",
                  "@/components/ui/input.tsx"]

imports:         ["react", "next/link", "next/navigation",
                  "react-hook-form", "@hookform/resolvers/zod",
                  "lucide-react", "sonner",
                  "@/components/ui/alert",
                  "@/components/ui/button",
                  "@/components/ui/field",
                  "@/components/ui/input",
                  "@/components/auth/PasswordInput",
                  "@/lib/auth/auth-client",
                  "@/lib/validations/auth"]

exports:         ["LoginForm", "LoginFormProps"]

useBy:           ["@/app/auth/login/page.tsx"]

userStories:     ["*en tant qu'utilisateur je veux me connecter avec mon email"]

status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
*/

"use client";
// "use client" justifié : useState, useForm, useRouter, toast, interactions utilisateur.

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { AlertCircle, ArrowRight, Loader2, Lock, Mail } from "lucide-react";
import { toast } from "sonner";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { PasswordInput } from "@/components/auth/PasswordInput";
import { signIn } from "@/lib/auth/auth-client";
import {
  loginSchema,
  type LoginInput,
} from "@/lib/validations/auth";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface LoginFormProps {
  readonly callbackUrl: string;
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function LoginForm({ callbackUrl }: LoginFormProps) {
  const router = useRouter();
  const [formError, setFormError] = useState<string | null>(null);
  const [redirecting, setRedirecting] = useState(false);

  const {
    control,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<LoginInput>({
    resolver: zodResolver(loginSchema),
    defaultValues: { email: "", password: "" },
    mode: "onBlur",
    reValidateMode: "onChange",
  });

  const isPending = isSubmitting || redirecting;

  async function onSubmit(values: LoginInput) {
    setFormError(null);

    try {
      const { error } = await signIn.email({
        email: values.email,
        password: values.password,
      });

      if (error) {
        if (error.status === 401 || error.status === 400) {
          setFormError("Email ou mot de passe incorrect.");
        } else if (error.status === 429) {
          setFormError("Trop de tentatives. Réessayez dans un instant.");
        } else {
          setFormError(error.message ?? "Connexion impossible. Réessayez.");
        }
        return;
      }

      setRedirecting(true);
      toast.success("Connexion réussie");
      router.replace(callbackUrl);
      router.refresh();
    } catch {
      setFormError(
        "Impossible de joindre le serveur. Vérifiez votre connexion.",
      );
    }
  }

  return (
    <div className="rounded-2xl border border-border bg-card p-6 shadow-xl shadow-chart-1/5 sm:p-8">
      {/* En-tête */}
      <div className="mb-8 space-y-3">
        <span className="grid size-11 place-items-center rounded-xl bg-gradient-to-br from-chart-1 to-chart-2 text-white shadow-lg shadow-chart-2/30">
          <Lock className="size-5" aria-hidden />
        </span>
        <h1 className="bg-gradient-to-r from-chart-1 via-chart-2 to-chart-3 bg-clip-text text-3xl font-bold tracking-tight text-transparent">
          Bon retour
        </h1>
        <p className="text-sm text-muted-foreground">
          Connectez-vous pour retrouver vos projets.
        </p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5" noValidate>
        {formError && (
          <Alert variant="destructive" role="alert">
            <AlertCircle className="size-4" aria-hidden />
            <AlertDescription>{formError}</AlertDescription>
          </Alert>
        )}

        {/* Email */}
        <Field data-invalid={errors.email ? "" : undefined}>
          <FieldLabel htmlFor="login-email">Email</FieldLabel>
          <div className="relative">
            <Mail
              className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"
              aria-hidden
            />
            <Controller
              control={control}
              name="email"
              render={({ field }) => (
                <Input
                  {...field}
                  id="login-email"
                  type="email"
                  inputMode="email"
                  autoComplete="email"
                  placeholder="vous@exemple.com"
                  className="h-11 pl-10"
                  aria-invalid={errors.email ? true : undefined}
                />
              )}
            />
          </div>
          {errors.email?.message && (
            <FieldError errors={[{ message: errors.email.message }]} />
          )}
        </Field>

        {/* Mot de passe */}
        <Field data-invalid={errors.password ? "" : undefined}>
          <FieldLabel htmlFor="login-password">Mot de passe</FieldLabel>
          <Controller
            control={control}
            name="password"
            render={({ field }) => (
              <PasswordInput
                {...field}
                id="login-password"
                autoComplete="current-password"
                placeholder="Votre mot de passe"
                aria-invalid={errors.password ? true : undefined}
              />
            )}
          />
          {errors.password?.message && (
            <FieldError errors={[{ message: errors.password.message }]} />
          )}
        </Field>

        <Button
          type="submit"
          disabled={isPending}
          className="h-11 w-full gap-2 bg-gradient-to-r from-chart-1 via-chart-2 to-chart-3 text-base font-semibold text-white shadow-lg shadow-chart-2/25 transition hover:brightness-110 disabled:opacity-70"
        >
          {isPending ? (
            <>
              <Loader2 className="size-4 animate-spin" aria-hidden />
              Connexion…
            </>
          ) : (
            <>
              Se connecter
              <ArrowRight className="size-4" aria-hidden />
            </>
          )}
        </Button>
      </form>

      <p className="mt-8 text-center text-sm text-muted-foreground">
        Pas encore de compte ?{" "}
        <Link
          href="/auth/register"
          className="font-semibold text-chart-1 hover:underline"
        >
          Créer un compte
        </Link>
      </p>
    </div>
  );
}

/*
