import { Suspense } from "react";
import { notFound } from "next/navigation";

import { getGroupBySlug } from "@/app/blog/lib/services/group";
import { resolveAuthorProfiles } from "@/app/blog/lib/services/author";
import { getBlogSession } from "@/app/blog/lib/session";
import { MemberActions } from "@/app/blog/components/MemberActions";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";
import { initialsOf } from "@/utils/initials";

type PageParams = Promise<{ groupSlug: string }>;

export default function BlogGroupRequestsPage({
  params,
}: {
  params: PageParams;
}) {
  return (
    <div className="mx-auto w-full max-w-3xl space-y-6 px-4 py-10 sm:px-6">
      <header className="space-y-1">
        <p className="text-[11px] font-semibold uppercase tracking-wider text-chart-2">
          Administration groupe
        </p>
        <h1 className="text-2xl font-bold tracking-tight text-foreground">
          Demandes d&apos;adhésion
        </h1>
      </header>
      <Suspense
        fallback={<Skeleton className="h-40 w-full rounded-2xl" />}
      >
        <RequestsSection params={params} />
      </Suspense>
    </div>
  );
}

async function RequestsSection({
  params,
}: {
  readonly params: PageParams;
}) {
  const { groupSlug } = await params;
  const group = await getGroupBySlug(groupSlug);
  if (!group) notFound();

  const session = await getBlogSession();
  if (!session?.user) notFound();
  const viewer = group.members.find(
    (m) => m.userId === session.user.id && m.status === "active",
  );
  if (!viewer || (viewer.role !== "owner" && viewer.role !== "moderator")) {
    notFound();
  }

  const pending = group.members.filter((m) => m.status === "pending");

  if (pending.length === 0) {
    return (
      <EmptyState
        title="Aucune demande en attente"
        description="Les nouvelles demandes d'adhésion apparaîtront ici."
      />
    );
  }

  /* Résolution nom + avatar des demandeurs (1 appel groupé). */
  const profiles = await resolveAuthorProfiles(
    pending.map((m) => m.userId),
  );

  return (
    <ul className="space-y-2">
      {pending.map((m) => {
        const profile = profiles.get(m.userId);
        const displayName = profile?.name ?? "Utilisateur inconnu";
        const avatarUrl = profile?.image ?? null;
        return (
          <li
            key={m.userId}
            className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border/60 bg-card p-4"
          >
            <div className="flex min-w-0 flex-1 items-center gap-3">
              <Avatar className="size-9 shrink-0">
                {avatarUrl && <AvatarImage src={avatarUrl} alt="" />}
                <AvatarFallback className="bg-gradient-to-br from-chart-2 to-chart-3 text-xs font-bold text-white">
                  {initialsOf(displayName)}
                </AvatarFallback>
              </Avatar>
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-foreground">
                  {displayName}
                </p>
                <p className="truncate text-xs text-muted-foreground">
                  {profile?.id ?? m.userId}
                </p>
              </div>
            </div>
            <MemberActions groupId={group.id} userId={m.userId} />
          </li>
        );
      })}
    </ul>
  );
}

