"use client";
// "use client" justifié : useState + useActionResult.

import { useState } from "react";
import { Loader2, Send } from "lucide-react";

import { createCommentAction } from "@/app/blog/lib/actions/comment";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { useActionResult } from "@/hooks/useActionResult";

export interface CommentFormProps {
  readonly articleId: string;
  readonly parentId: string;
  readonly isAuthenticated: boolean;
  readonly onSuccess?: () => void;
}

export function CommentForm({
  articleId,
  parentId,
  isAuthenticated,
  onSuccess,
}: CommentFormProps) {
  const [content, setContent] = useState("");
  const { run, isPending } = useActionResult();

  if (!isAuthenticated) {
    return (
      <p className="rounded-xl border border-dashed border-border/60 bg-muted/20 p-4 text-sm text-muted-foreground">
        Connectez-vous pour participer à la discussion.
      </p>
    );
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    const trimmed = content.trim();
    if (trimmed.length === 0) return;

    run(() => createCommentAction(articleId, parentId, trimmed), {
      successMessage: "Commentaire publié.",
      onSuccess: () => {
        setContent("");
        onSuccess?.();
      },
    });
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-2">
      <Textarea
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Écrire un commentaire…"
        rows={3}
        maxLength={5000}
        aria-label="Commentaire"
        className="resize-none"
      />
      <div className="flex justify-end">
        <Button
          type="submit"
          disabled={isPending || content.trim().length === 0}
          className="gap-2"
        >
          {isPending ? (
            <Loader2 className="size-4 animate-spin" aria-hidden />
          ) : (
            <Send className="size-4" aria-hidden />
          )}
          Envoyer
        </Button>
      </div>
    </form>
  );
}

