"use client";
// "use client" justifié : useState (optimiste) + useActionResult + toast.

import { useState } from "react";
import { Bookmark } from "lucide-react";
import { toast } from "sonner";

import { toggleFavoriteAction } from "@/app/blog/lib/actions/favorite";
import { Button } from "@/components/ui/button";
import { useActionResult } from "@/hooks/useActionResult";

export interface FavoriteButtonProps {
  readonly articleId: string;
  readonly initiallyFavorited: boolean;
  readonly isAuthenticated: boolean;
}

export function FavoriteButton({
  articleId,
  initiallyFavorited,
  isAuthenticated,
}: FavoriteButtonProps) {
  const [favorited, setFavorited] = useState(initiallyFavorited);
  const { run, isPending } = useActionResult();

  function handleClick() {
    if (!isAuthenticated) {
      toast.error("Connectez-vous pour sauvegarder cet article.");
      return;
    }
    const prev = favorited;
    setFavorited(!favorited);

    run(() => toggleFavoriteAction(articleId), {
      successMessage: false,
      rollback: () => setFavorited(prev),
      onSuccess: (data) => setFavorited(data.favorited),
    });
  }

  return (
    <Button
      type="button"
      variant={favorited ? "secondary" : "outline"}
      onClick={handleClick}
      disabled={isPending}
      aria-pressed={favorited}
      aria-label={favorited ? "Retirer des favoris" : "Ajouter aux favoris"}
      className="gap-2"
    >
      <Bookmark
        className={`size-4 ${favorited ? "fill-current" : ""}`}
        aria-hidden
      />
      {favorited ? "Sauvegardé" : "Sauvegarder"}
    </Button>
  );
}

