"use client";
// "use client" justifié : useActionResult (client hook).

import Link from "next/link";
import { LogIn, LogOut, Settings } from "lucide-react";

import {
  joinGroupAction,
  leaveGroupAction,
} from "@/app/blog/lib/actions/group";
import type { Group } from "@/app/blog/lib/types";
import { Button } from "@/components/ui/button";
import { useActionResult } from "@/hooks/useActionResult";

export interface GroupActionsProps {
  readonly group: Group;
  readonly isMember: boolean;
  readonly isOwnerOrMod: boolean;
  readonly isAuthenticated: boolean;
}

export function GroupActions({
  group,
  isMember,
  isOwnerOrMod,
  isAuthenticated,
}: GroupActionsProps) {
  const { run, isPending } = useActionResult();

  function join() {
    run(() => joinGroupAction(group.id), {
      successMessage:
        group.visibility === "public"
          ? "Vous avez rejoint le groupe."
          : "Demande envoyée.",
    });
  }

  function leave() {
    run(() => leaveGroupAction(group.id), {
      successMessage: "Vous avez quitté le groupe.",
    });
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      {isOwnerOrMod && (
        <Button
          render={
            <Link href={`/blog/community/${group.slug}/requests`} />
          }
          size="sm"
          variant="outline"
          className="gap-1.5"
        >
          <Settings className="size-3.5" aria-hidden />
          Demandes
        </Button>
      )}
      {!isAuthenticated ? (
        <Button
          render={<Link href="/core/auth/login" />}
          size="sm"
          className="gap-1.5"
        >
          <LogIn className="size-3.5" aria-hidden />
          Se connecter
        </Button>
      ) : isMember ? (
        <Button
          type="button"
          size="sm"
          variant="outline"
          onClick={leave}
          disabled={isPending}
          className="gap-1.5"
        >
          <LogOut className="size-3.5" aria-hidden />
          Quitter
        </Button>
      ) : (
        <Button
          type="button"
          size="sm"
          onClick={join}
          disabled={isPending}
          className="gap-1.5"
        >
          <LogIn className="size-3.5" aria-hidden />
          {group.visibility === "public" ? "Rejoindre" : "Demander à rejoindre"}
        </Button>
      )}
    </div>
  );
}

