"use client";
// "use client" justifié : useState (optimiste) + useActionResult + toast.

import { useState } from "react";
import { Heart } from "lucide-react";
import { toast } from "sonner";

import { toggleArticleLikeAction } from "@/app/blog/lib/actions/like";
import { Button } from "@/components/ui/button";
import { useActionResult } from "@/hooks/useActionResult";

export interface LikeButtonProps {
  readonly articleId: string;
  readonly initialCount: number;
  readonly initiallyLiked: boolean;
  readonly isAuthenticated: boolean;
}

export function LikeButton({
  articleId,
  initialCount,
  initiallyLiked,
  isAuthenticated,
}: LikeButtonProps) {
  const [liked, setLiked] = useState(initiallyLiked);
  const [count, setCount] = useState(initialCount);
  const { run, isPending } = useActionResult();

  function handleClick() {
    if (!isAuthenticated) {
      toast.error("Connectez-vous pour liker cet article.");
      return;
    }
    const prev = { liked, count };
    setLiked(!liked);
    setCount(liked ? Math.max(0, count - 1) : count + 1);

    run(() => toggleArticleLikeAction(articleId), {
      successMessage: false,
      rollback: () => {
        setLiked(prev.liked);
        setCount(prev.count);
      },
      onSuccess: (data) => {
        setLiked(data.liked);
        setCount(data.count);
      },
    });
  }

  return (
    <Button
      type="button"
      variant={liked ? "default" : "outline"}
      onClick={handleClick}
      disabled={isPending}
      aria-pressed={liked}
      aria-label={liked ? "Retirer le like" : "Liker l'article"}
      className="gap-2"
    >
      <Heart
        className={`size-4 ${liked ? "fill-current" : ""}`}
        aria-hidden
      />
      {count}
    </Button>
  );
}

