"use client";
// "use client" justifié : useActionResult (client hook).

import { Bell, Check, Trash2 } from "lucide-react";

import {
  deleteNotificationAction,
  markAllAsReadAction,
  markAsReadAction,
} from "@/app/blog/lib/actions/notification";
import type { Notification } from "@/app/blog/lib/types";
import { Button } from "@/components/ui/button";
import { formatDateTime } from "@/utils/date";
import { useActionResult } from "@/hooks/useActionResult";

export interface NotificationListProps {
  readonly items: readonly Notification[];
}

const TYPE_LABEL: Record<Notification["type"], string> = {
  reply: "Réponse",
  group_invite: "Invitation de groupe",
  group_join_approved: "Adhésion approuvée",
  group_new_discussion: "Nouvelle discussion",
};

export function NotificationList({ items }: NotificationListProps) {
  const { run, isPending } = useActionResult();
  const unread = items.filter((n) => !n.readAt).length;

  function markAll() {
    run(() => markAllAsReadAction(), {
      successMessage: "Toutes les notifications sont lues.",
    });
  }

  function markOne(id: string) {
    run(() => markAsReadAction(id), { successMessage: false });
  }

  function remove(id: string) {
    run(() => deleteNotificationAction(id), { successMessage: false });
  }

  if (items.length === 0) {
    return (
      <div className="rounded-2xl border border-dashed border-border/60 bg-muted/20 p-12 text-center">
        <Bell
          className="mx-auto mb-2 size-8 text-muted-foreground"
          aria-hidden
        />
        <p className="text-sm text-muted-foreground">
          Aucune notification pour l&apos;instant.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground">
          {unread} non lue{unread > 1 ? "s" : ""} sur {items.length}
        </p>
        {unread > 0 && (
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={markAll}
            disabled={isPending}
            className="gap-1.5"
          >
            <Check className="size-3.5" aria-hidden />
            Tout marquer lu
          </Button>
        )}
      </div>

      <ul className="space-y-2">
        {items.map((n) => (
          <li
            key={n.id}
            className={`flex flex-col gap-2 rounded-xl border p-4 sm:flex-row sm:items-start ${
              n.readAt
                ? "border-border/60 bg-muted/10"
                : "border-chart-1/40 bg-chart-1/5"
            }`}
          >
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-baseline gap-2 text-xs">
                <span className="font-semibold text-foreground">
                  {TYPE_LABEL[n.type]}
                </span>
                <span className="text-muted-foreground">
                  · {formatDateTime(n.createdAt)}
                </span>
                {!n.readAt && (
                  <span className="rounded-full bg-chart-1/20 px-2 py-0.5 text-[10px] font-semibold uppercase text-chart-1">
                    Nouveau
                  </span>
                )}
              </div>
              <p className="mt-1 line-clamp-2 text-sm text-foreground/90">
                {n.excerpt}
              </p>
            </div>
            <div className="flex shrink-0 gap-1">
              {!n.readAt && (
                <Button
                  type="button"
                  size="icon-xs"
                  variant="ghost"
                  onClick={() => markOne(n.id)}
                  disabled={isPending}
                  aria-label="Marquer comme lu"
                >
                  <Check aria-hidden />
                </Button>
              )}
              <Button
                type="button"
                size="icon-xs"
                variant="ghost"
                onClick={() => remove(n.id)}
                disabled={isPending}
                className="text-destructive hover:bg-destructive/10 hover:text-destructive"
                aria-label="Supprimer la notification"
              >
                <Trash2 aria-hidden />
              </Button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

