import Link from "next/link";

/* ------------------------------------------------------------------ */
/*  Props                                                              */
/* ------------------------------------------------------------------ */

export interface PaginationBarProps {
  /** Page courante (1-indexée). */
  readonly page: number;
  /** Nombre total de pages. */
  readonly totalPages: number;
  /** Construit le href pour une page donnée (ex. `(p) => `/blog?page=${p}`). */
  readonly buildHref: (page: number) => string;
  /** Nombre max de pages visibles avant troncature. Défaut : 7. */
  readonly maxVisible?: number;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

const ELLIPSIS = "…" as const;
type PageItem = number | typeof ELLIPSIS;

/**
 * Retourne la liste des pages visibles avec ellipsis si dépassement.
 * Toujours : première page, dernière page, courante ± 1.
 */
function computeVisiblePages(
  page: number,
  totalPages: number,
  maxVisible: number,
): readonly PageItem[] {
  if (totalPages <= maxVisible) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const pages = new Set<number>([1, totalPages, page]);
  pages.add(Math.max(2, page - 1));
  pages.add(Math.min(totalPages - 1, page + 1));

  const sorted = Array.from(pages).sort((a, b) => a - b);

  const items: PageItem[] = [];
  for (let i = 0; i < sorted.length; i++) {
    const current = sorted[i];
    const previous = sorted[i - 1];
    if (i > 0 && previous !== undefined && current - previous > 1) {
      items.push(ELLIPSIS);
    }
    items.push(current);
  }
  return items;
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function PaginationBar({
  page,
  totalPages,
  buildHref,
  maxVisible = 7,
}: PaginationBarProps) {
  if (totalPages <= 1) return null;

  const items = computeVisiblePages(page, totalPages, maxVisible);

  return (
    <nav
      aria-label="Pagination"
      className="flex flex-wrap items-center justify-center gap-2"
    >
      {items.map((item, index) => {
        if (item === ELLIPSIS) {
          return (
            <span
              key={`ellipsis-${index}`}
              aria-hidden
              className="inline-flex h-9 min-w-9 items-center justify-center px-3 text-sm text-muted-foreground"
            >
              {ELLIPSIS}
            </span>
          );
        }

        const active = item === page;
        return (
          <Link
            key={item}
            href={buildHref(item)}
            className={
              active
                ? "inline-flex h-9 min-w-9 items-center justify-center rounded-md bg-primary px-3 text-sm font-semibold text-primary-foreground"
                : "inline-flex h-9 min-w-9 items-center justify-center rounded-md border border-border/60 px-3 text-sm text-muted-foreground hover:bg-muted"
            }
            aria-current={active ? "page" : undefined}
          >
            {item}
          </Link>
        );
      })}
    </nav>
  );
}

