/* ------------------------------------------------------------------ */
/*  Props                                                              */
/* ------------------------------------------------------------------ */

export interface QuickCreateCategoryDialogProps {
  readonly open: boolean;
  readonly onOpenChange: (open: boolean) => void;
  readonly themeId: string;
  /** Requis si mode === "subcategory". */
  readonly categoryId?: string;
  readonly mode: "category" | "subcategory";
  /** Callback : nouvelle entité créée, id retourné. */
  readonly onCreated: (id: string) => void;
}

/* ------------------------------------------------------------------ */
/*  Composant                                                          */
/* ------------------------------------------------------------------ */

export function QuickCreateCategoryDialog({
  open,
  onOpenChange,
  themeId,
  categoryId,
  mode,
  onCreated,
}: QuickCreateCategoryDialogProps) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const { run, isPending } = useActionResult();

  const isSub = mode === "subcategory";

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    const trimmed = name.trim();
    if (trimmed.length === 0) {
      toast.error("Le nom est requis.");
      return;
    }

    const formData = new FormData();
    formData.set("name", trimmed);
    formData.set("description", description.trim());

    run(
      () =>
        isSub
          ? categoryId
            ? createSubCategoryAction(themeId, categoryId, formData)
            : Promise.resolve({
                ok: false as const,
                error: "Catégorie parente manquante.",
              })
          : createCategoryAction(themeId, formData),
      {
        successMessage: isSub
          ? "Sous-catégorie créée."
          : "Catégorie créée.",
        onSuccess: (data) => {
          onCreated(data.id);
          setName("");
          setDescription("");
          onOpenChange(false);
        },
      },
    );
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>
            {isSub ? "Nouvelle sous-catégorie" : "Nouvelle catégorie"}
          </DialogTitle>
          <DialogDescription>
            {isSub
              ? "Ajoutée à la catégorie sélectionnée, sans quitter le formulaire."
              : "Ajoutée au thème sélectionné, sans quitter le formulaire."}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <Field>
            <FieldLabel htmlFor="quick-name">Nom</FieldLabel>
            <Input
              id="quick-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              maxLength={80}
              autoFocus
              disabled={isPending}
            />
          </Field>

          <Field>
            <FieldLabel htmlFor="quick-desc">
              Description (optionnel)
            </FieldLabel>
            <Textarea
              id="quick-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={2}
              maxLength={200}
              disabled={isPending}
            />
          </Field>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isPending}
            >
              Annuler
            </Button>
            <Button type="submit" disabled={isPending || !name.trim()}>
              {isPending ? (
                <Loader2 className="size-4 animate-spin" aria-hidden />
              ) : (
                <Plus className="size-4" aria-hidden />
              )}
              Créer
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

