  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Field, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useActionResult } from "@/hooks/useActionResult";

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

type EntityKind = "theme" | "category" | "subcategory";

interface EditTarget {
  readonly kind: EntityKind;
  readonly themeId?: string;
  readonly categoryId?: string;
  readonly entity?: Theme | Category | SubCategory;
}

export interface TaxonomyFormProps {
  readonly themes: readonly Theme[];
}

/* ------------------------------------------------------------------ */
/*  Composant principal                                                */
/* ------------------------------------------------------------------ */

export function TaxonomyForm({ themes }: TaxonomyFormProps) {
  const [openThemeId, setOpenThemeId] = useState<string | null>(null);
  const [editing, setEditing] = useState<EditTarget | null>(null);
  const [deleting, setDeleting] = useState<EditTarget | null>(null);
  const { run, isPending } = useActionResult();

  function openCreate(
    kind: EntityKind,
    parent: { themeId?: string; categoryId?: string } = {},
  ) {
    setEditing({ kind, ...parent });
  }

  function openEdit(target: EditTarget) {
    setEditing(target);
  }

  function handleDelete() {
    if (!deleting) return;

    if (deleting.kind === "theme" && deleting.themeId) {
      run(() => deleteThemeAction(deleting.themeId!), {
        successMessage: "Supprimé.",
        onSuccess: () => setDeleting(null),
      });
    } else if (
      deleting.kind === "category" &&
      deleting.themeId &&
      deleting.categoryId
    ) {
      run(
        () =>
          deleteCategoryAction(deleting.themeId!, deleting.categoryId!),
        {
          successMessage: "Supprimé.",
          onSuccess: () => setDeleting(null),
        },
      );
    } else if (
      deleting.kind === "subcategory" &&
      deleting.themeId &&
      deleting.categoryId &&
      deleting.entity
    ) {
      run(
        () =>
          deleteSubCategoryAction(
            deleting.themeId!,
            deleting.categoryId!,
            deleting.entity!.id,
          ),
        {
          successMessage: "Supprimé.",
          onSuccess: () => setDeleting(null),
        },
      );
    }
  }

  return (
    <div className="space-y-4">
      <header className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h2 className="text-lg font-bold tracking-tight text-foreground">
            Taxonomie
          </h2>
          <p className="text-sm text-muted-foreground">
            {themes.length} thème{themes.length > 1 ? "s" : ""} · hiérarchie
            3 niveaux
          </p>
        </div>
        <Button
          type="button"
          onClick={() => openCreate("theme")}
          className="gap-2"
        >
          <Plus className="size-4" aria-hidden />
          Nouveau thème
        </Button>
      </header>

      {themes.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border/60 bg-muted/20 p-10 text-center">
          <Layers className="mx-auto size-8 text-muted-foreground" aria-hidden />
          <p className="mt-2 text-sm text-muted-foreground">
            Aucun thème pour l&apos;instant.
          </p>
        </div>
      ) : (
        <Accordion
          multiple={false}
          defaultValue={[]}
          value={openThemeId ? [openThemeId] : []}
          onValueChange={(values: string[]) =>
            setOpenThemeId(values[0] ?? null)
          }
        >
          {themes.map((theme) => (
            <AccordionItem
              key={theme.id}
              value={theme.id}
              className="rounded-xl border border-border/60 bg-card not-last:mb-2"
            >
              <AccordionTrigger className="px-4 py-3 hover:no-underline">
                <div className="flex flex-1 items-center gap-3 text-left">
                  <span
                    className="grid size-9 shrink-0 place-items-center rounded-lg text-white shadow-sm"
                    style={{
                      background: `linear-gradient(135deg, var(--${theme.color}), color-mix(in oklab, var(--${theme.color}) 60%, black))`,
                    }}
                    aria-hidden
                  >
                    <Layers className="size-4" />
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-bold text-foreground">
                      {theme.name}
                    </p>
                    <p className="truncate text-[11px] text-muted-foreground">
                      /{theme.slug} · {theme.categories.length} catégorie
                      {theme.categories.length > 1 ? "s" : ""}
                    </p>
                  </div>
                </div>
              </AccordionTrigger>
              <AccordionContent className="space-y-2 px-4 pb-4">
                <div className="flex flex-wrap gap-2 pb-2">
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    onClick={() =>
                      openEdit({
                        kind: "theme",
                        themeId: theme.id,
                        entity: theme,
                      })
                    }
                    className="gap-1.5"
                  >
                    <Pencil className="size-3.5" aria-hidden />
                    Éditer le thème
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    onClick={() =>
                      openCreate("category", { themeId: theme.id })
                    }
                    className="gap-1.5"
                  >
                    <Plus className="size-3.5" aria-hidden />
                    Ajouter une catégorie
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    variant="ghost"
                    onClick={() =>
                      setDeleting({ kind: "theme", themeId: theme.id })
                    }
                    className="gap-1.5 text-destructive hover:bg-destructive/10 hover:text-destructive"
                  >
                    <Trash2 className="size-3.5" aria-hidden />
                    Supprimer
                  </Button>
                </div>

                {theme.categories.length === 0 ? (
                  <p className="rounded-lg border border-dashed border-border/60 bg-muted/20 p-3 text-center text-xs text-muted-foreground">
                    Aucune catégorie dans ce thème.
                  </p>
                ) : (
                  <ul className="space-y-2">
                    {theme.categories.map((cat) => (
                      <li
                        key={cat.id}
                        className="rounded-lg border border-border/60 bg-muted/10 p-3"
                      >
                        <div className="flex flex-wrap items-center gap-2">
                          <FolderTree
                            className="size-4 shrink-0 text-chart-2"
                            aria-hidden
                          />
                          <div className="min-w-0 flex-1">
                            <p className="truncate text-sm font-semibold text-foreground">
                              {cat.name}
                            </p>
                            <p className="truncate text-[11px] text-muted-foreground">
                              /{cat.slug} · {cat.subCategories.length}{" "}
                              sous-catégorie
                              {cat.subCategories.length > 1 ? "s" : ""}
                            </p>
                          </div>
                          <div className="flex flex-wrap gap-1">
                            <Button
                              type="button"
                              size="icon-xs"
                              variant="ghost"
                              onClick={() =>
                                openEdit({
                                  kind: "category",
                                  themeId: theme.id,
                                  categoryId: cat.id,
                                  entity: cat,
                                })
                              }
                              aria-label={`Éditer ${cat.name}`}
                            >
                              <Pencil aria-hidden />
                            </Button>
                            <Button
                              type="button"
                              size="icon-xs"
                              variant="ghost"
                              onClick={() =>
                                openCreate("subcategory", {
                                  themeId: theme.id,
                                  categoryId: cat.id,
                                })
                              }
                              aria-label={`Ajouter une sous-catégorie à ${cat.name}`}
                            >
                              <Plus aria-hidden />
                            </Button>
                            <Button
                              type="button"
                              size="icon-xs"
                              variant="ghost"
                              onClick={() =>
                                setDeleting({
                                  kind: "category",
                                  themeId: theme.id,
                                  categoryId: cat.id,
                                })
                              }
                              aria-label={`Supprimer ${cat.name}`}
                              className="text-destructive hover:bg-destructive/10 hover:text-destructive"
                            >
                              <Trash2 aria-hidden />
                            </Button>
                          </div>
                        </div>

                        {cat.subCategories.length > 0 && (
                          <ul className="mt-2 space-y-1 pl-6">
                            {cat.subCategories.map((sub) => (
                              <li
                                key={sub.id}
                                className="flex items-center gap-2 rounded-md bg-background/60 px-2 py-1"
                              >
                                <ChevronRight
                                  className="size-3 shrink-0 text-muted-foreground"
                                  aria-hidden
                                />
                                <p className="min-w-0 flex-1 truncate text-xs text-foreground/90">
                                  {sub.name}{" "}
                                  <span className="text-muted-foreground">
                                    /{sub.slug}
                                  </span>
                                </p>
                                <Button
                                  type="button"
                                  size="icon-xs"
                                  variant="ghost"
                                  onClick={() =>
                                    openEdit({
                                      kind: "subcategory",
                                      themeId: theme.id,
                                      categoryId: cat.id,
                                      entity: sub,
                                    })
                                  }
                                  aria-label={`Éditer ${sub.name}`}
                                >
                                  <Pencil aria-hidden />
                                </Button>
                                <Button
                                  type="button"
                                  size="icon-xs"
                                  variant="ghost"
                                  onClick={() =>
                                    setDeleting({
                                      kind: "subcategory",
                                      themeId: theme.id,
                                      categoryId: cat.id,
                                      entity: sub,
                                    })
                                  }
                                  aria-label={`Supprimer ${sub.name}`}
                                  className="text-destructive hover:bg-destructive/10 hover:text-destructive"
                                >
                                  <Trash2 aria-hidden />
                                </Button>
                              </li>
                            ))}
                          </ul>
                        )}
                      </li>
                    ))}
                  </ul>
                )}
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      )}

      <EntityDialog
        target={editing}
        onClose={() => setEditing(null)}
        onSuccess={() => setEditing(null)}
      />

      <AlertDialog
        open={deleting !== null}
        onOpenChange={(open) => !open && setDeleting(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmer la suppression</AlertDialogTitle>
            <AlertDialogDescription>
              Cette action est définitive. La suppression est refusée si
              l&apos;entité contient des enfants.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isPending}>Annuler</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={isPending}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isPending && (
                <Loader2 className="size-4 animate-spin" aria-hidden />
              )}
              Supprimer
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Dialog d'édition unifiée                                          */
/* ------------------------------------------------------------------ */

interface EntityDialogProps {
  readonly target: EditTarget | null;
  readonly onClose: () => void;
  readonly onSuccess: () => void;
}

function EntityDialog({ target, onClose, onSuccess }: EntityDialogProps) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [color, setColor] = useState("chart-1");
  const [icon, setIcon] = useState("Sparkles");
  const [error, setError] = useState<string | null>(null);
  const { run, isPending } = useActionResult();

  /* Reset à chaque nouvelle cible */
  const targetKey = target
    ? `${target.kind}:${target.themeId ?? ""}:${target.categoryId ?? ""}:${target.entity?.id ?? "new"}`
    : "";
  const [lastKey, setLastKey] = useState<string>("");
  if (targetKey !== lastKey) {
    setLastKey(targetKey);
    const entity = target?.entity;
    setName(entity?.name ?? "");
    setDescription(
      entity && "description" in entity ? (entity.description ?? "") : "",
    );
    if (entity && "color" in entity) setColor(entity.color ?? "chart-1");
    if (entity && "icon" in entity) setIcon(entity.icon ?? "Sparkles");
    setError(null);
  }

  if (!target) return null;

  const titleByKind: Record<EntityKind, string> = {
    theme: target.entity ? "Éditer le thème" : "Nouveau thème",
    category: target.entity ? "Éditer la catégorie" : "Nouvelle catégorie",
    subcategory: target.entity
      ? "Éditer la sous-catégorie"
      : "Nouvelle sous-catégorie",
  };

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    const formData = new FormData();
    formData.set("name", name.trim());
    formData.set("description", description.trim());
    if (target?.kind === "theme") {
      formData.set("color", color.trim() || "chart-1");
      formData.set("icon", icon.trim() || "Sparkles");
    }

    if (target?.kind === "theme") {
      run(
        () =>
          target.entity
            ? updateThemeAction(target.entity.id, formData)
            : createThemeAction(formData),
        {
          successMessage: "Enregistré.",
          onError: setError,
          onSuccess: () => onSuccess(),
        },
      );
    } else if (target?.kind === "category" && target.themeId) {
      run(
        () =>
          target.entity
            ? updateCategoryAction(
                target.themeId!,
                target.entity.id,
                formData,
              )
            : createCategoryAction(target.themeId!, formData),
        {
          successMessage: "Enregistré.",
          onError: setError,
          onSuccess: () => onSuccess(),
        },
      );
    } else if (
      target?.kind === "subcategory" &&
      target.themeId &&
      target.categoryId
    ) {
      run(
        () =>
          target.entity
            ? updateSubCategoryAction(
                target.themeId!,
                target.categoryId!,
                target.entity.id,
                formData,
              )
            : createSubCategoryAction(
                target.themeId!,
                target.categoryId!,
                formData,
              ),
        {
          successMessage: "Enregistré.",
          onError: setError,
          onSuccess: () => onSuccess(),
        },
      );
    }
  }

  return (
    <Dialog open={true} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{titleByKind[target.kind]}</DialogTitle>
          <DialogDescription>
            Le slug est généré automatiquement à partir du nom.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <p
              role="alert"
              className="rounded-lg border border-destructive/40 bg-destructive/5 p-2 text-xs text-destructive"
            >
              {error}
            </p>
          )}

          <Field>
            <FieldLabel htmlFor="entity-name">Nom</FieldLabel>
            <Input
              id="entity-name"
              value={name}
              onChange={(event) => setName(event.target.value)}
              required
              maxLength={100}
            />
          </Field>

          <Field>
            <FieldLabel htmlFor="entity-description">
              Description (optionnel)
            </FieldLabel>
            <Textarea
              id="entity-description"
              value={description}
              onChange={(event) => setDescription(event.target.value)}
              rows={3}
              maxLength={500}
            />
          </Field>

          {target.kind === "theme" && (
            <div className="grid grid-cols-2 gap-3">
              <Field>
                <FieldLabel htmlFor="entity-color">Couleur</FieldLabel>
                <Input
                  id="entity-color"
                  value={color}
                  onChange={(event) => setColor(event.target.value)}
                  maxLength={50}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor="entity-icon">Icône (Lucide)</FieldLabel>
                <Input
                  id="entity-icon"
                  value={icon}
                  onChange={(event) => setIcon(event.target.value)}
                  maxLength={50}
                />
              </Field>
            </div>
          )}

          <div className="flex justify-end gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={isPending}
            >
              Annuler
            </Button>
            <Button type="submit" disabled={isPending || !name.trim()}>
              {isPending ? (
                <Loader2 className="size-4 animate-spin" aria-hidden />
              ) : (
                <Save className="size-4" aria-hidden />
              )}
              Enregistrer
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

