const STORAGE_PIPELINE: readonly string[] = [
  "ArticleForm.tsx construit un FormData (title, summary, content JSON, …).",
  "createArticleAction(formData) — Server Action — requireBlogSession() puis articleInputSchema.parse().",
  "createArticle(authorId, input) — service — appelle validateArticleTaxonomy() AVANT le lock (theme/cat/subCat/tags doivent exister dans taxonomy.json).",
  "withGlobalArticleLock() — sérialise l'attribution d'order (mutex GLOBAL, cible _index.json + création).",
  "listArticleFiles() → findFreeSlug() → writeArticleFile(article) — écriture atomique de data/blog/[slug].json.",
  "Écriture atomique : writeFile('<slug>.json.<UUID>.tmp') puis rename(...). Le suffixe UUID évite les collisions entre deux writes concurrents (gotcha Windows).",
];

const STORAGE_GUARANTEES: readonly string[] = [
  "Trois mutex indépendants : GLOBAL (_index.json + création article), TAXONOMIE (taxonomy.json), PAR-ARTICLE ([slug].json). Deux articles mutent en parallèle.",
  "Écriture atomique (.tmp suffixé d'un UUID + rename) : jamais de fichier à moitié écrit, même en cas de crash.",
  "Validation Zod à la lecture ET à l'écriture : articleSchema (arbres content[] ≤ 6, comments[] ≤ 5), taxonomySchema, blogDocumentSchema.",
  "BLOG_SCHEMA_VERSION = 3. readTaxonomyFile normalise les fichiers legacy incomplets (champs manquants comblés) avant parse ; la prochaine mutation persiste la forme canonique.",
  "Un fichier par article : data/blog/[slug].json. data/blog/_index.json garde les playlists, groupes, notifications, favoris, meta.adminIds. data/blog/taxonomy.json est le référentiel admin (thèmes + tags).",
];

