"use server";

import { revalidatePath } from "next/cache";
import { ZodError } from "zod";

import {
  handleActionError,
  type ActionResult,
} from "@/app/blog/lib/actions/result";
import { isAdmin } from "@/app/blog/lib/admin";
import { requireBlogSession } from "@/app/blog/lib/session";
import { createArticle } from "@/app/blog/lib/services/article";
import {
  createTag,
  listTags,
  listThemes,
} from "@/app/blog/lib/services/taxonomy";
import type { ContentBlock, Tag, Theme } from "@/app/blog/lib/types";
import {
  importArticleSchema,
  type ImportBlock,
} from "@/app/blog/lib/validations/article-import";
import { slugify } from "@/utils/slugify";

/* ------------------------------------------------------------------ */
/*  Normalisation des blocs                                          */
/* ------------------------------------------------------------------ */

function normalizeImportBlocks(
  raw: readonly ImportBlock[],
  articleId: string,
): ContentBlock[] {
  const now = new Date().toISOString();
  return raw.map((block, index) => ({
    ...block,
    id: crypto.randomUUID(),
    parentId: articleId,
    order: index,
    createdAt: now,
    updatedAt: now,
  })) as ContentBlock[];
}

/* ------------------------------------------------------------------ */
/*  Résolution par id puis par slug/name                              */
/* ------------------------------------------------------------------ */

function matchBySlugOrName<T extends { slug: string; name: string }>(
  items: readonly T[],
  query: string,
): T | undefined {
  const q = query.trim().toLowerCase();
  const qSlug = slugify(query);
  return (
    items.find((item) => item.slug === qSlug) ??
    items.find((item) => item.name.toLowerCase() === q)
  );
}

interface Resolved<T> {
  readonly entity: T;
  readonly via: "id" | "name";
}

function resolveTheme(
  themes: readonly Theme[],
  input: { themeId?: string; themeName?: string },
): Resolved<Theme> | { error: string } {
  if (input.themeId) {
    const found = themes.find((t) => t.id === input.themeId);
    if (!found) {
      const available = themes.map((t) => `${t.name} (${t.id})`).join(", ");
      return {
        error: `Thème introuvable par id "${input.themeId}". Disponibles : ${available || "aucun"}.`,
      };
    }
    return { entity: found, via: "id" };
  }
  if (input.themeName) {
    const found = matchBySlugOrName(themes, input.themeName);
    if (!found) {
      const available = themes.map((t) => t.name).join(", ");
      return {
        error: `Thème introuvable : "${input.themeName}". Disponibles : ${available || "aucun"}.`,
      };
    }
    return { entity: found, via: "name" };
  }
  return { error: "themeId ou themeName requis." };
}

/* ------------------------------------------------------------------ */
/*  Action                                                            */
/* ------------------------------------------------------------------ */

export interface ImportResult {
  readonly id: string;
  readonly slug: string;
  readonly createdTags: readonly string[];
  readonly resolved: {
    readonly theme: "id" | "name";
    readonly category: "id" | "name" | null;
    readonly subCategory: "id" | "name" | null;
  };
}

export async function importArticleFromJsonAction(
  rawJson: string,
): Promise<ActionResult<ImportResult>> {
  try {
    const session = await requireBlogSession();

    /* 1. Parse + validation */
    let parsed: unknown;
    try {
      parsed = JSON.parse(rawJson);
    } catch {
      return { ok: false, error: "JSON invalide : syntaxe incorrecte." };
    }

    let validated;
    try {
      validated = importArticleSchema.parse(parsed);
    } catch (error) {
      if (error instanceof ZodError) {
        const issues = error.issues
          .map((i) => `${i.path.join(".") || "racine"} : ${i.message}`)
          .join(" · ");
        return { ok: false, error: `Validation : ${issues}` };
      }
      throw error;
    }

    /* 2. Thème */
    const themes = await listThemes();
    const themeResult = resolveTheme(themes, {
      themeId: validated.themeId,
      themeName: validated.themeName,
    });
    if ("error" in themeResult) return { ok: false, error: themeResult.error };
    const theme = themeResult.entity;

    /* 3. Catégorie (id prioritaire, name fallback) */
    let categoryId: string | undefined;
    let categoryVia: "id" | "name" | null = null;
    if (validated.categoryId) {
      const cat = theme.categories.find((c) => c.id === validated.categoryId);
      if (!cat) {
        const available = theme.categories
          .map((c) => `${c.name} (${c.id})`)
          .join(", ");
        return {
          ok: false,
          error: `Catégorie introuvable par id "${validated.categoryId}" dans "${theme.name}". Disponibles : ${available || "aucune"}.`,
        };
      }
      categoryId = cat.id;
      categoryVia = "id";
    } else if (validated.categoryName) {
      const cat = matchBySlugOrName(theme.categories, validated.categoryName);
      if (!cat) {
        const available = theme.categories.map((c) => c.name).join(", ");
        return {
          ok: false,
          error: `Catégorie introuvable dans "${theme.name}" : "${validated.categoryName}". Disponibles : ${available || "aucune"}.`,
        };
      }
      categoryId = cat.id;
      categoryVia = "name";
    }

    /* 4. Sous-catégorie (id prioritaire, name fallback) */
    let subCategoryId: string | undefined;
    let subCategoryVia: "id" | "name" | null = null;
    if (validated.subCategoryId || validated.subCategoryName) {
      if (!categoryId) {
        return {
          ok: false,
          error:
            "subCategoryId / subCategoryName requiert categoryId / categoryName.",
        };
      }
      const cat = theme.categories.find((c) => c.id === categoryId)!;
      if (validated.subCategoryId) {
        const sub = cat.subCategories.find(
          (s) => s.id === validated.subCategoryId,
        );
        if (!sub) {
          const available = cat.subCategories
            .map((s) => `${s.name} (${s.id})`)
            .join(", ");
          return {
            ok: false,
            error: `Sous-catégorie introuvable par id "${validated.subCategoryId}". Disponibles : ${available || "aucune"}.`,
          };
        }
        subCategoryId = sub.id;
        subCategoryVia = "id";
      } else if (validated.subCategoryName) {
        const sub = matchBySlugOrName(
          cat.subCategories,
          validated.subCategoryName,
        );
        if (!sub) {
          const available = cat.subCategories.map((s) => s.name).join(", ");
          return {
            ok: false,
            error: `Sous-catégorie introuvable : "${validated.subCategoryName}". Disponibles : ${available || "aucune"}.`,
          };
        }
        subCategoryId = sub.id;
        subCategoryVia = "name";
      }
    }

    /* 5. Tags (ids priorité, names créés si admin) */
    const existingTags = await listTags();
    const admin = await isAdmin();
    const tagIds: string[] = [];
    const createdTags: string[] = [];
    const missingForNonAdmin: string[] = [];

    /* 5a. IDs fournis → lookup exact */
    for (const id of validated.tagIds) {
      const tag = existingTags.find((t: Tag) => t.id === id);
      if (!tag) {
        return {
          ok: false,
          error: `Tag introuvable par id "${id}".`,
        };
      }
      if (!tagIds.includes(tag.id)) tagIds.push(tag.id);
    }

    /* 5b. Names fournis → match slug/name, sinon création (admin) */
    for (const rawName of validated.tagNames) {
      const name = rawName.trim();
      if (!name) continue;
      const existing = matchBySlugOrName(existingTags, name);
      if (existing) {
        if (!tagIds.includes(existing.id)) tagIds.push(existing.id);
        continue;
      }
      if (!admin) {
        missingForNonAdmin.push(name);
        continue;
      }
      const created = await createTag({ name });
      tagIds.push(created.id);
      createdTags.push(name);
    }

    if (missingForNonAdmin.length > 0) {
      return {
        ok: false,
        error: `Tags inconnus : ${missingForNonAdmin.join(", ")}. Créez-les depuis /blog/taxonomy (seul un admin peut les créer à l'import).`,
      };
    }

    /* 6. Normalisation des blocs (id article pré-généré) */
    const articleId = crypto.randomUUID();
    const content = normalizeImportBlocks(validated.content, articleId);

    /* 7. Création */
    const article = await createArticle(
      session.user.id,
      {
        title: validated.title,
        summary: validated.summary,
        coverImage: validated.coverImage,
        themeId: theme.id,
        categoryId,
        subCategoryId,
        tagIds,
        status: validated.status,
        visibility: validated.visibility,
        featured: validated.featured,
        content,
      },
      { id: articleId },
    );

    /* 8. Revalidation */
    revalidatePath("/blog/articles");
    revalidatePath("/blog");

    return {
      ok: true,
      data: {
        id: article.id,
        slug: article.slug,
        createdTags,
        resolved: {
          theme: themeResult.via,
          category: categoryVia,
          subCategory: subCategoryVia,
        },
      },
    };
  } catch (error) {
    return handleActionError(error);
  }
}

