import {
  mkdir,
  readFile,
  readdir,
  rename,
  unlink,
  writeFile,
} from "node:fs/promises";
import { dirname, join } from "node:path";

import type {
  Article,
  BlogDocument,
  Category,
  SubCategory,
  Tag,
  Taxonomy,
  Theme,
} from "@/app/blog/lib/types";
