/* ------------------------------------------------------------------ */
/*  Chemins                                                           */
/* ------------------------------------------------------------------ */

const DATA_DIR = join(process.cwd(), "data");
const BLOG_DIR = join(DATA_DIR, "blog");

export function blogFilePath(): string {
  return join(BLOG_DIR, "_index.json");
}

export function taxonomyFilePath(): string {
  return join(BLOG_DIR, "taxonomy.json");
}

export function articleFilePath(slug: string): string {
  return join(BLOG_DIR, `${slug}.json`);
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                           */
/* ------------------------------------------------------------------ */

function isENOENT(error: unknown): boolean {
  return (
    error instanceof Error &&
    "code" in error &&
    (error as NodeJS.ErrnoException).code === "ENOENT"
  );
}

async function atomicWrite(path: string, data: string): Promise<void> {
  const tmp = `${path}.${crypto.randomUUID()}.tmp`;
  await mkdir(dirname(path), { recursive: true });
  await writeFile(tmp, data, "utf-8");
  try {
    await rename(tmp, path);
  } catch (error) {
    await unlink(tmp).catch(() => {});
    throw error;
  }
}

type Resolver = () => void;

function makeMutex(): { acquire: () => Promise<Resolver> } {
  let pending: Promise<void> = Promise.resolve();
  async function acquire(): Promise<Resolver> {
    let release!: Resolver;
    const next = new Promise<void>((resolve) => {
      release = resolve;
    });
    const previous = pending;
    pending = pending.then(() => next);
    await previous;
    return release;
  }
  return { acquire };
}

/* ------------------------------------------------------------------ */
/*  Document vide (_index.json)                                       */
/* ------------------------------------------------------------------ */

export function createEmptyBlogDocument(): BlogDocument {
  return {
    meta: {
      schemaVersion: BLOG_SCHEMA_VERSION,
      updatedAt: new Date().toISOString(),
      adminIds: [],
    },
    taxonomy: { themes: [], tags: [] },
    playlists: [],
    articles: [],
    groups: [],
    userContent: {},
    auditLog: [],
  };
}

/* ------------------------------------------------------------------ */
/*  Migration v2 → v3 (in-memory)                                     */
/* ------------------------------------------------------------------ */

function migrateToCurrentVersion(raw: unknown): unknown {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return raw;
  const doc = raw as Record<string, unknown>;
  const meta = doc.meta as Record<string, unknown> | undefined;
  const version =
    typeof meta?.schemaVersion === "number" ? meta.schemaVersion : undefined;

  if (version === undefined || version === BLOG_SCHEMA_VERSION) return raw;

  if (version === 2) {
    return {
      ...doc,
      playlists: Array.isArray(doc.playlists) ? doc.playlists : [],
      meta: {
        ...meta,
        schemaVersion: BLOG_SCHEMA_VERSION,
        updatedAt: new Date().toISOString(),
      },
    };
  }

  return raw;
}

/* ------------------------------------------------------------------ */
/*  Normalisation taxonomie — tolère les fichiers incomplets         */
/* ------------------------------------------------------------------ */

/**
 * Normalise un objet taxonomie arbitraire vers la forme canonique.
 *
 * - Remplit les champs manquants avec des fallbacks déterministes :
 *   id, slug, name basés sur la position (`legacy-theme-0`, etc.) — donc
 *   STABLES entre deux lectures tant qu'aucune mutation n'a persisté la
 *   forme normalisée.
 * - color → "chart-1", icon → "Sparkles", order → index, timestamps → now.
 * - Renvoie `{ themes: [], tags: [] }` si l'objet est totalement invalide.
 *
 * Utilisation : readTaxonomyFile(normalise AVANT parse). La prochaine
 * mutation réécrit le fichier en forme canonique — pas de perte de
 * données.
 */
export function normalizeTaxonomy(raw: unknown): Taxonomy {
  const now = new Date().toISOString();
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return { themes: [], tags: [] };
  }
  const doc = raw as Record<string, unknown>;
  const rawThemes = Array.isArray(doc.themes) ? doc.themes : [];
  const rawTags = Array.isArray(doc.tags) ? doc.tags : [];

  const themes: Theme[] = rawThemes.map((t, i) => {
    const th = (t ?? {}) as Record<string, unknown>;
    const rawCats = Array.isArray(th.categories) ? th.categories : [];

    const categories: Category[] = rawCats.map((c, j) => {
      const ca = (c ?? {}) as Record<string, unknown>;
      const rawSubs = Array.isArray(ca.subCategories) ? ca.subCategories : [];

      const subCategories: SubCategory[] = rawSubs.map((s, k) => {
        const su = (s ?? {}) as Record<string, unknown>;
        return {
          id:
            typeof su.id === "string" && su.id.length > 0
              ? su.id
              : `legacy-sub-${i}-${j}-${k}`,
          slug:
            typeof su.slug === "string" && su.slug.length > 0
              ? su.slug
              : `sous-categorie-${i}-${j}-${k}`,
          name:
            typeof su.name === "string" && su.name.length > 0
              ? su.name
              : `Sous-catégorie ${k + 1}`,
          description:
            typeof su.description === "string" ? su.description : undefined,
          order: typeof su.order === "number" ? su.order : k,
          createdAt: typeof su.createdAt === "string" ? su.createdAt : now,
          updatedAt: typeof su.updatedAt === "string" ? su.updatedAt : now,
        };
      });

      return {
        id:
          typeof ca.id === "string" && ca.id.length > 0
            ? ca.id
            : `legacy-cat-${i}-${j}`,
        slug:
          typeof ca.slug === "string" && ca.slug.length > 0
            ? ca.slug
            : `categorie-${i}-${j}`,
        name:
          typeof ca.name === "string" && ca.name.length > 0
            ? ca.name
            : `Catégorie ${j + 1}`,
        description:
          typeof ca.description === "string" ? ca.description : undefined,
        order: typeof ca.order === "number" ? ca.order : j,
        createdAt: typeof ca.createdAt === "string" ? ca.createdAt : now,
        updatedAt: typeof ca.updatedAt === "string" ? ca.updatedAt : now,
        subCategories,
      };
    });

    return {
      id:
        typeof th.id === "string" && th.id.length > 0
          ? th.id
          : `legacy-theme-${i}`,
      slug:
        typeof th.slug === "string" && th.slug.length > 0
          ? th.slug
          : `theme-${i + 1}`,
      name:
        typeof th.name === "string" && th.name.length > 0
          ? th.name
          : `Thème ${i + 1}`,
      description:
        typeof th.description === "string" ? th.description : undefined,
      color:
        typeof th.color === "string" && th.color.length > 0
          ? th.color
          : "chart-1",
      icon:
        typeof th.icon === "string" && th.icon.length > 0
          ? th.icon
          : "Sparkles",
      order: typeof th.order === "number" ? th.order : i,
      createdAt: typeof th.createdAt === "string" ? th.createdAt : now,
      updatedAt: typeof th.updatedAt === "string" ? th.updatedAt : now,
      categories,
    };
  });

  const tags: Tag[] = rawTags.map((t, i) => {
    const ta = (t ?? {}) as Record<string, unknown>;
    return {
      id:
        typeof ta.id === "string" && ta.id.length > 0
          ? ta.id
          : `legacy-tag-${i}`,
      slug:
        typeof ta.slug === "string" && ta.slug.length > 0
          ? ta.slug
          : `tag-${i + 1}`,
      name:
        typeof ta.name === "string" && ta.name.length > 0
          ? ta.name
          : `Tag ${i + 1}`,
      color: typeof ta.color === "string" ? ta.color : undefined,
      createdAt: typeof ta.createdAt === "string" ? ta.createdAt : now,
      updatedAt: typeof ta.updatedAt === "string" ? ta.updatedAt : now,
    };
  });

  return { themes, tags };
}

/**
 * Détecte si un objet taxonomie brut contenait des champs manquants.
 * Utilisé uniquement pour logger un warning (pas de logique métier).
 */
function taxonomyNeedsNormalization(raw: unknown): boolean {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return true;
  const doc = raw as Record<string, unknown>;
  const themes = Array.isArray(doc.themes) ? doc.themes : [];
  const tags = Array.isArray(doc.tags) ? doc.tags : [];
  if (themes.length === 0 && tags.length === 0) return false;

  for (const t of themes) {
    const th = (t ?? {}) as Record<string, unknown>;
    if (
      typeof th.id !== "string" ||
      typeof th.slug !== "string" ||
      typeof th.name !== "string" ||
      typeof th.color !== "string" ||
      typeof th.icon !== "string" ||
      typeof th.order !== "number" ||
      typeof th.createdAt !== "string" ||
      typeof th.updatedAt !== "string"
    ) {
      return true;
    }
  }
  for (const t of tags) {
    const ta = (t ?? {}) as Record<string, unknown>;
    if (
      typeof ta.id !== "string" ||
      typeof ta.slug !== "string" ||
      typeof ta.name !== "string" ||
      typeof ta.createdAt !== "string" ||
      typeof ta.updatedAt !== "string"
    ) {
      return true;
    }
  }
  return false;
}

/* ------------------------------------------------------------------ */
/*  Mutex global (_index.json + createArticle)                       */
/* ------------------------------------------------------------------ */

const globalMutex = makeMutex();

export async function withGlobalArticleLock<T>(
  fn: () => Promise<T>,
): Promise<T> {
  const release = await globalMutex.acquire();
  try {
    return await fn();
  } finally {
    release();
  }
}

/* ------------------------------------------------------------------ */
/*  Lecture / mutation _index.json                                    */
/* ------------------------------------------------------------------ */

export async function readBlog(): Promise<BlogDocument> {
  const path = blogFilePath();

  try {
    const raw = await readFile(path, "utf-8");
    const parsed: unknown = JSON.parse(raw);
    const migrated = migrateToCurrentVersion(parsed);
    return blogDocumentSchema.parse(migrated) as BlogDocument;
  } catch (error) {
    if (!isENOENT(error)) throw error;

    try {
      const empty = createEmptyBlogDocument();
      await atomicWrite(path, JSON.stringify(empty, null, 2));
      return empty;
    } catch (writeError) {
      try {
        const raw = await readFile(path, "utf-8");
        const parsed: unknown = JSON.parse(raw);
        const migrated = migrateToCurrentVersion(parsed);
        return blogDocumentSchema.parse(migrated) as BlogDocument;
      } catch {
        throw writeError;
      }
    }
  }
}

export async function mutateBlog<T>(
  fn: (doc: BlogDocument) => BlogDocument | Promise<BlogDocument>,
): Promise<T> {
  const release = await globalMutex.acquire();
  try {
    const current = await readBlog();
    const next = await fn(current);
    const validated = blogDocumentSchema.parse({
      ...next,
      meta: { ...next.meta, updatedAt: new Date().toISOString() },
    }) as BlogDocument;
    await atomicWrite(blogFilePath(), JSON.stringify(validated, null, 2));
    return validated as unknown as T;
  } finally {
    release();
  }
}

/* ------------------------------------------------------------------ */
/*  Mutex taxonomie (dédié — distinct du global)                     */
/* ------------------------------------------------------------------ */

const taxonomyMutex = makeMutex();

/* ------------------------------------------------------------------ */
/*  Lecture taxonomie (avec normalisation défensive)                 */
/* ------------------------------------------------------------------ */

export async function readTaxonomyFile(): Promise<Taxonomy> {
  try {
    const rawText = await readFile(taxonomyFilePath(), "utf-8");
    const rawParsed: unknown = JSON.parse(rawText);

    /* ⚠️ Normalise AVANT le parse strict : tolère les fichiers incomplets
       (données legacy, hand-edit). Les IDs manquants reçoivent un fallback
       déterministe basé sur la position, donc stable entre lectures. La
       prochaine mutation persiste la forme canonique. */
    if (taxonomyNeedsNormalization(rawParsed)) {
      console.warn(
        "[blog/storage] data/blog/taxonomy.json contenait des champs manquants — normalisé en mémoire. La prochaine mutation persistera la forme canonique.",
      );
    }

    const normalized = normalizeTaxonomy(rawParsed);
    return taxonomySchema.parse(normalized) as Taxonomy;
  } catch (error) {
    if (isENOENT(error)) return { themes: [], tags: [] };
    throw error;
  }
}

/* ------------------------------------------------------------------ */
/*  Écriture taxonomie                                                */
/* ------------------------------------------------------------------ */

export async function writeTaxonomyFile(taxonomy: Taxonomy): Promise<void> {
  const validated = taxonomySchema.parse(taxonomy) as Taxonomy;
  await atomicWrite(taxonomyFilePath(), JSON.stringify(validated, null, 2));
}

/* ------------------------------------------------------------------ */
/*  Mutation taxonomie                                                */
/* ------------------------------------------------------------------ */

export async function mutateTaxonomyFile(
  fn: (taxonomy: Taxonomy) => Taxonomy | Promise<Taxonomy>,
): Promise<Taxonomy> {
  const release = await taxonomyMutex.acquire();
  try {
    const current = await readTaxonomyFile();
    const next = await fn(current);
    const validated = taxonomySchema.parse(next) as Taxonomy;
    await atomicWrite(taxonomyFilePath(), JSON.stringify(validated, null, 2));
    return validated;
  } finally {
    release();
  }
}

/* ------------------------------------------------------------------ */
/*  Mutex par article                                                 */
/* ------------------------------------------------------------------ */

const articleLocks = new Map<string, Promise<void>>();

async function withArticleLock<T>(
  slug: string,
  fn: () => Promise<T>,
): Promise<T> {
  const previous = articleLocks.get(slug) ?? Promise.resolve();
  let release!: Resolver;
  const current = new Promise<void>((resolve) => {
    release = resolve;
  });
  const chained = previous.then(() => current);
  articleLocks.set(slug, chained);
  await previous;
  try {
    return await fn();
  } finally {
    release();
    if (articleLocks.get(slug) === chained) {
      articleLocks.delete(slug);
    }
  }
}

/* ------------------------------------------------------------------ */
/*  Articles                                                          */
/* ------------------------------------------------------------------ */

export async function readArticleFile(slug: string): Promise<Article | null> {
  try {
    const raw = await readFile(articleFilePath(slug), "utf-8");
    return articleSchema.parse(JSON.parse(raw)) as Article;
  } catch (error) {
    if (isENOENT(error)) return null;
    throw error;
  }
}

export async function writeArticleFile(article: Article): Promise<void> {
  const validated = articleSchema.parse(article) as Article;
  await atomicWrite(
    articleFilePath(validated.slug),
    JSON.stringify(validated, null, 2),
  );
}

export async function deleteArticleFile(slug: string): Promise<void> {
  try {
    await unlink(articleFilePath(slug));
  } catch (error) {
    if (!isENOENT(error)) throw error;
  }
}

export async function listArticleFiles(): Promise<readonly Article[]> {
  let entries: string[];
  try {
    entries = await readdir(BLOG_DIR);
  } catch (error) {
    if (isENOENT(error)) return [];
    throw error;
  }

  const files = entries.filter(
    (entry) => entry.endsWith(".json") && !entry.startsWith("_"),
  );
  const articleFiles = files.filter((f) => f !== "taxonomy.json");

  const articles = await Promise.all(
    articleFiles.map((file) => readArticleFile(file.replace(/\.json$/, ""))),
  );
  return articles
    .filter((a): a is Article => a !== null)
    .sort((a, b) => a.order - b.order);
}

export async function mutateArticleFile(
  slug: string,
  fn: (article: Article) => Article | Promise<Article>,
): Promise<Article> {
  return withArticleLock(slug, async () => {
    const current = await readArticleFile(slug);
    if (!current) {
      throw new Error(`[blog/storage] Article introuvable : ${slug}`);
    }
    const next = await fn(current);
    const validated = articleSchema.parse({
      ...next,
      updatedAt: new Date().toISOString(),
    }) as Article;
    await writeArticleFile(validated);
    return validated;
  });
}

