    schemaVersion: z.literal(BLOG_SCHEMA_VERSION),
    updatedAt: isoDate,
    adminIds: z.array(z.string().min(1)),
  })
  .strict();

/* ------------------------------------------------------------------ */
/*  Document résiduel (_index.json)                                   */
/*  - articles[] → toujours vide (articles dans [slug].json)          */
/*  - taxonomy   → toujours vide (taxonomie dans taxonomy.json)       */
/* ------------------------------------------------------------------ */

export const blogDocumentSchema = z
  .object({
    meta: blogMetaSchema,
    taxonomy: taxonomySchema,          // ⚠️ toujours { themes: [], tags: [] }
    playlists: z.array(playlistSchema),
    articles: z.array(articleSchema),  // ⚠️ toujours []
    groups: z.array(groupSchema),
    userContent: userContentMapSchema,
    auditLog: z.array(auditEntrySchema),
  })
  .strict()
  .superRefine((doc, ctx) => {
    /* Seuls les arbres posts[] des groupes restent validés ici. */
    doc.groups.forEach((group, gi) => {
      group.discussions.forEach((disc, di) => {
        validateTreeStructure(
          disc.posts,
          disc.id,
          5,
          ctx,
          ["groups", gi, "discussions", di, "posts"],
        );
      });
    });

    /* Unicité article ↔ playlist (l'existence est vérifiée à l'écriture
       par addArticleToPlaylist — cf. R5 FlowBlog.md). */
    const playlistIds = new Set<string>();
    const articleToPlaylist = new Map<string, string>();

    doc.playlists.forEach((playlist, pi) => {
      if (playlistIds.has(playlist.id)) {
        ctx.addIssue({
          code: "custom",
          message: `Playlist id dupliqué : "${playlist.id}"`,
          path: ["playlists", pi],
        });
      }
      playlistIds.add(playlist.id);

      playlist.articleIds.forEach((articleId, ai) => {
        if (articleToPlaylist.has(articleId)) {
          ctx.addIssue({
            code: "custom",
            message: `Article "${articleId}" présent dans plusieurs playlists`,
            path: ["playlists", pi, "articleIds", ai],
          });
        } else {
          articleToPlaylist.set(articleId, playlist.id);
        }
      });
    });
  });

