import { Suspense } from "react";
import { Search as SearchIcon } from "lucide-react";

import { searchArticles } from "@/app/blog/lib/services/search";
import { listTags, listThemes } from "@/app/blog/lib/services/taxonomy";
import { ArticleCard } from "@/app/blog/components/ArticleCard";
import { SearchFilters } from "@/app/blog/components/SearchFilters";
import { PaginationBar } from "@/app/blog/components/PaginationBar";
import { EmptyState } from "@/components/ui/empty-state";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";

type SearchParams = Promise<Record<string, string | undefined>>;

export default function BlogSearchPage({
  searchParams,
}: {
  searchParams: SearchParams;
}) {
  return (
    <Suspense fallback={<SearchSkeleton />}>
      <SearchSection searchParams={searchParams} />
    </Suspense>
  );
}

async function SearchSection({
  searchParams,
}: {
  readonly searchParams: SearchParams;
}) {
  const sp = await searchParams;
  const q = sp.q ?? "";
  const page = Math.max(1, Number(sp.page ?? "1") || 1);
  const themeSlug = sp.theme?.trim() || undefined;
  const tagSlug = sp.tag?.trim() || undefined;
  const featured = sp.featured === "1";

  /* Thèmes + tags pour les filtres */
  const [themes, tags] = await Promise.all([listThemes(), listTags()]);

  const result = await searchArticles({
    q,
    themeSlug,
    tagSlugs: tagSlug ? [tagSlug] : undefined,
    featured: sp.featured === undefined ? undefined : featured,
    page,
    pageSize: 20,
  });

  /* buildHref : préserve q, theme, tag, featured, change juste page. */
  const buildPageHref = (p: number): string => {
    const params = new URLSearchParams();
    if (q) params.set("q", q);
    if (themeSlug) params.set("theme", themeSlug);
    if (tagSlug) params.set("tag", tagSlug);
    if (featured) params.set("featured", "1");
    if (p > 1) params.set("page", String(p));
    const qs = params.toString();
    return qs ? `/blog/search?${qs}` : "/blog/search";
  };

  return (
    <div className="mx-auto w-full max-w-6xl space-y-8 px-4 py-10 sm:px-6 lg:py-14">
      <header className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight text-foreground">
          Recherche
        </h1>
        <p className="text-sm text-muted-foreground">
          {result.total} résultat{result.total > 1 ? "s" : ""} pour «{" "}
          {q || "tout"} »
        </p>
      </header>

      {/* Formulaire texte rapide */}
      <form action="/blog/search" method="get" className="flex gap-2">
        <Input
          type="search"
          name="q"
          defaultValue={q}
          placeholder="Rechercher un article…"
          aria-label="Recherche"
          className="flex-1"
        />
        {themeSlug && <input type="hidden" name="theme" value={themeSlug} />}
        {tagSlug && <input type="hidden" name="tag" value={tagSlug} />}
        {featured && <input type="hidden" name="featured" value="1" />}
        <Button type="submit" className="gap-2">
          <SearchIcon className="size-4" aria-hidden />
          Rechercher
        </Button>
      </form>

      {/* Filtres combinables */}
      <SearchFilters
        themes={themes}
        tags={tags}
        current={{
          q,
          themeSlug,
          tagSlug,
          featured,
        }}
      />

      {result.items.length === 0 ? (
        <EmptyState
          title="Aucun article ne correspond"
          description="Essayez d'élargir vos critères ou de retirer certains filtres."
        />
      ) : (
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {result.items.map((article) => (
            <ArticleCard key={article.id} article={article} />
          ))}
        </div>
      )}

      <PaginationBar
        page={result.page}
        totalPages={result.totalPages}
        buildHref={buildPageHref}
      />
    </div>
  );
}

function SearchSkeleton() {
  return (
    <div className="mx-auto w-full max-w-6xl space-y-8 px-4 py-10 sm:px-6">
      <Skeleton className="h-9 w-48" />
      <Skeleton className="h-10 w-full" />
      <Skeleton className="h-32 w-full rounded-2xl" />
      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
        <Skeleton className="h-72 rounded-2xl" />
        <Skeleton className="h-72 rounded-2xl" />
        <Skeleton className="h-72 rounded-2xl" />
      </div>
    </div>
  );
}

