  readonly label: string;
  readonly icon: LucideIcon;
  readonly accent: string;
  readonly key: keyof Pick<
    ScrumDocument,
    "idea" | "feature" | "persona" | "epic" | "userStory" | "sprint" | "task" // ← AJOUT
  >;
}

/* ------------------------------------------------------------------ */
/*  Config                                                             */
/* ------------------------------------------------------------------ */

const SECTIONS: readonly SectionEntry[] = [
  {
    slug: "idee",
    label: "Idées",
    icon: Lightbulb,
    accent: "chart-1",
    key: "idea",
