                  "@/app/core/components/scrum/UserStoryList.tsx"]

userStories:     ["*en tant qu'utilisateur je veux réorganiser les cartes par glisser-déposer"]

status:          planned
pathChecked:     ✘false
metaDataChecked: ✘false
scriptChecked:   ✘false
