            placeholder="+33 6 12 34 56 78"
            autoComplete="tel"
          />
        </Field>
      </section>

      {/* ----------------------------------------------------------- */}
      {/*  Actions                                                    */}
      {/* ----------------------------------------------------------- */}
      <div className="flex flex-wrap justify-end gap-2">
        {dirty && (
          <Button
            type="button"
            variant="ghost"
            onClick={handleReset}
            disabled={isPending}
          >
            Réinitialiser
          </Button>
        )}
        <Button
          type="submit"
          disabled={isPending || !dirty || name.trim().length < 2}
          className="gap-2"
        >
          {isPending ? (
            <Loader2 className="size-4 animate-spin" aria-hidden />
          ) : (
            <Save className="size-4" aria-hidden />
          )}
          Enregistrer
        </Button>
      </div>
    </form>
  );
}

